&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Cam&#233;roc&#233;ras&lt;div style=&quot;float:right;&quot;&gt;FP 11&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Animal&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Animal.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Aquatique&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Aquatique.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Temp&#233;r&#233;&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Temp&#233;r&#233;.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire 5 p.51&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 12 800
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Animal.html&quot; title=&quot;Animal&quot;&gt;Animal&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Aquatique.html&quot; title=&quot;Aquatique (sous-type)&quot;&gt;aquatique&lt;/a&gt;) de taille TG, N
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +6 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Odorat-Surd&#233;velopp&#233;-(Capacit&#233;).html&quot; title=&quot;Odorat surd&#233;velopp&#233; (Ext)&quot;&gt;odorat surd&#233;velopp&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +15
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 25, contact 10, pris au d&#233;pourvu 23 (Dex +2, naturelle +15, taille -2)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 152 (16d8+80)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +12, &lt;b&gt;Vig&lt;/b&gt; +15, &lt;b&gt;Vol&lt;/b&gt; +10
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 1,50 m, nage 6 m, &lt;a class=&quot;pagelink&quot; href=&quot;Propulsion-(Capacit&#233;).html&quot; title=&quot;Propulsion (Ext)&quot;&gt;propulsion&lt;/a&gt; 27 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; tentacules, +19 (4d8+9/19-20 plus &lt;a class=&quot;pagelink&quot; href=&quot;&#201;treinte-(Capacit&#233;).html&quot; title=&quot;&#201;treinte (Ext)&quot;&gt;&#233;treinte&lt;/a&gt;) et morsure, +19 (2d8+9/19-20)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Espace occup&#233;&lt;/b&gt; 4,50 m ; &lt;b&gt;Allonge&lt;/b&gt; 4,50 m
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; ceinturage, &lt;a class=&quot;pagelink&quot; href=&quot;Constriction-(Capacit&#233;).html&quot; title=&quot;Constriction (Ext)&quot;&gt;constriction&lt;/a&gt; (4d8+13)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 28, &lt;b&gt;Dex&lt;/b&gt; 14, &lt;b&gt;Con&lt;/b&gt; 21, &lt;b&gt;Int&lt;/b&gt; 2, &lt;b&gt;Sag&lt;/b&gt; 17, &lt;b&gt;Cha&lt;/b&gt; 5
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +12 ; &lt;b&gt;BMO&lt;/b&gt; +23 (+27 en &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt;) ; &lt;b&gt;DMD&lt;/b&gt; 35 (croc-en-jambe impossible)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-R&#233;flexes.html&quot; title=&quot;Attaques r&#233;flexes&quot;&gt;Attaques r&#233;flexes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Combat-En-Aveugle.html&quot; title=&quot;Combat en aveugle&quot;&gt;Combat en aveugle&lt;/a&gt;&lt;sup&gt;S&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Fente.html&quot; title=&quot;Fente&quot;&gt;Fente&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Frappe-D&#233;cisive.html&quot; title=&quot;Frappe d&#233;cisive&quot;&gt;Frappe d&#233;cisive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l&#39;initiative&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Critique.html&quot; title=&quot;Science du critique&quot;&gt;Science du critique&lt;/a&gt; (morsure), &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Critique.html&quot; title=&quot;Science du critique&quot;&gt;Science du critique&lt;/a&gt; (tentacules), &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; (Discr&#233;tion), &lt;a class=&quot;pagelink&quot; href=&quot;Volont&#233;-De-Fer.html&quot; title=&quot;Volont&#233; de fer&quot;&gt;Volont&#233; de fer&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +14, &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt; +17, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +15 ; &lt;b&gt;Modificateurs raciaux&lt;/b&gt; +4 en Perception
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Particularit&#233;s&lt;/b&gt; acclimat&#233; &#224; la pression, coquille, tentacules
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;&#201;cologie&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Environnement&lt;/b&gt; oc&#233;ans
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Organisation&lt;/b&gt; solitaire ou couple
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Tr&#233;sor&lt;/b&gt; fortuit
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Pouvoirs sp&#233;ciaux&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Acclimat&#233; &#224; la pression (Ext).&lt;/b&gt; Un cam&#233;roc&#233;ras ne subit aucun d&#233;g&#226;t inflig&#233; par la pression &#224; une profondeur de moins de 1,5 kilom&#232;tre, m&#234;me s’il se retrouve instantan&#233;ment &#224; une profondeur o&#249; la pression est diff&#233;rente.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Ceinturage (Ext).&lt;/b&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt;, un cam&#233;roc&#233;ras peut maintenir sa prise en situation de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt;, comme s’il poss&#233;dait le don &lt;a class=&quot;pagelink&quot; href=&quot;Lutte-Sup&#233;rieure.html&quot; title=&quot;Lutte sup&#233;rieure&quot;&gt;Lutte sup&#233;rieure&lt;/a&gt;, mais s’il le fait, il doit d&#233;cider d’immobiliser sa cible.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Coquille (Ext).&lt;/b&gt; Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt;, un cam&#233;roc&#233;ras peut rentrer ses extr&#233;mit&#233;s dans sa coquille, avec une cr&#233;ature de taille M ou jusqu’&#224; deux cr&#233;atures de taille P ou plus petites qu’il agrippe, et refermer la coquille en faisant coulisser un &#171; couvercle &#187; amovible sur l’ouverture. Il ne peut pas voir, sentir, ou attaquer des cr&#233;atures situ&#233;es &#224; l’ext&#233;rieur de sa coquille tant qu’il reste enferm&#233; de cette fa&#231;on, mais son bonus d’armure naturelle &#224; la CA augmente de +6. Il ne peut pas se d&#233;placer, si ce n’est pour nager &#224; la verticale en modifiant la pression des cavit&#233;s internes ; il perd son bonus de Dext&#233;rit&#233; &#224; la CA contre des adversaires situ&#233;s &#224; l’ext&#233;rieur. Une cr&#233;ature qui &#233;chappe &#224; la prise du cam&#233;roc&#233;ras &#224; l’int&#233;rieur de sa coquille en sort et celle-ci se referme derri&#232;re lui. On peut enfoncer le couvercle de la coquille gr&#226;ce &#224; un test de manœuvre offensive de lutte, l’attaquer depuis l’int&#233;rieur (CA 19) ou l’attaquer depuis l’ext&#233;rieur en r&#233;ussissant un test de manœuvre offensive de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Destruction.html&quot; title=&quot;destruction&quot;&gt;destruction&lt;/a&gt;. Le couvercle de la coquille poss&#232;de une solidit&#233; de 10 et 15 points de r&#233;sistance. Le cam&#233;roc&#233;ras peut sortir de sa coquille par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;.
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Tentacules (Ext).&lt;/b&gt; Un cam&#233;roc&#233;ras effectue une seule attaque primaire avec l’ensemble de ses tentacules.
&lt;/div&gt;
&lt;/div&gt;&lt;/td&gt;
&lt;td&gt;&lt;div&gt;&lt;i&gt;De l’extr&#233;mit&#233; &#233;vid&#233;e d’un long coquillage en forme de c&#244;ne surgit une &#233;norme cr&#233;ature dot&#233;e d’yeux impassibles au-dessus d’un amas de tentacules.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Pr&#233;dateur embusqu&#233; primordial que l’on trouve souvent dans les profondeurs oc&#233;aniques o&#249; la lumi&#232;re du soleil est trop faible pour permettre le d&#233;veloppement d’une quelconque flore marine, le cam&#233;roc&#233;ras est un danger s&#233;rieux pour ceux qui osent explorer l’oc&#233;an. Un cam&#233;roc&#233;ras peut survivre jusqu’&#224; une profondeur maximale de 1,5 kilom&#232;tre, car sa coquille est suffisamment r&#233;sistante pour supporter la pression de l’eau &#224; cette profondeur. Il ne peut toutefois pas survivre tr&#232;s longtemps &#224; des profondeurs plus grandes. De temps &#224; autre, la faim pousse ces animaux &#224; remonter vers des eaux moins profondes et plus claires. Quand un cam&#233;roc&#233;ras ceinture ses proies avec ses tentacules, il peut rentrer dans sa coquille avec la cr&#233;ature sans d&#233;fense et rejoindre le fond de l’oc&#233;an pour la d&#233;vorer en toute tranquillit&#233;.&lt;br /&gt;&lt;br /&gt;Un cam&#233;roc&#233;ras moyen fait 7,50 m&#232;tres de long et la majorit&#233; de cette longueur inclut sa longue coquille. Celle-ci est en grande partie creuse et c’est pour cette raison que la plupart des sp&#233;cimens ne p&#232;sent qu’une tonne environ. En plus des tentacules avec lesquels il attrape ses proies, un cam&#233;roc&#233;ras poss&#232;de quatre tentacules sp&#233;ciaux qui lui conf&#232;rent un odorat particuli&#232;rement d&#233;velopp&#233;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Le cam&#233;roc&#233;ras comme &lt;a class=&quot;pagelink&quot; href=&quot;Liste-Des-Compagnons-Animaux.html&quot; title=&quot;Liste des compagnons animaux du druide&quot;&gt;compagnon animal&lt;/a&gt;&lt;a class=&quot;headeranchor&quot; id=&quot;Le_cam&#233;roc&#233;ras_comme_compagnon_animal__0&quot; href=&quot;#Le_cam&#233;roc&#233;ras_comme_compagnon_animal__0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;b&gt;Caract&#233;ristiques de d&#233;part :&lt;/b&gt; &lt;b&gt;Taille&lt;/b&gt; M ; &lt;b&gt;Vitesse&lt;/b&gt; 1,50 m, nage 6 m, propulsion 27 m ; &lt;b&gt;CA&lt;/b&gt; armure naturelle +1 ; &lt;b&gt;Attaque&lt;/b&gt; tentacules (1d4 plus &lt;a class=&quot;pagelink&quot; href=&quot;&#201;treinte-(Capacit&#233;).html&quot; title=&quot;&#201;treinte (Ext)&quot;&gt;&#233;treinte&lt;/a&gt;), morsure (1d3) ; &lt;b&gt;Caract&#233;ristiques&lt;/b&gt; For 14, Dex 15, Con 11, Int 2, Sag 12, Cha 2 ; &lt;b&gt;Particularit&#233;s&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt;, acclimat&#233; &#224; la pression&lt;br /&gt;&lt;br /&gt;&lt;b&gt;D&#233;veloppement au niveau 7 :&lt;/b&gt; &lt;b&gt;Taille&lt;/b&gt; G ; &lt;b&gt;CA&lt;/b&gt; armure naturelle +2 ; &lt;b&gt;Attaque&lt;/b&gt; tentacules (1d6 plus &lt;a class=&quot;pagelink&quot; href=&quot;&#201;treinte-(Capacit&#233;).html&quot; title=&quot;&#201;treinte (Ext)&quot;&gt;&#233;treinte&lt;/a&gt;), morsure (1d4) ; &lt;b&gt;Caract&#233;ristiques&lt;/b&gt; For +4, Dex -2, Con +2 ; &lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Constriction-(Capacit&#233;).html&quot; title=&quot;Constriction (Ext)&quot;&gt;constriction&lt;/a&gt; (1d6)
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
